insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-pe-185","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Beryllium has a higher first ionisation enthalpy than boron because Be has a","options":["half-filled 2p set","filled 2s subshell","larger atomic radius than Li","vacant 1s orbital"],"answer_index":1,"explanation":"Removing an electron from stable 2s² (Be) costs more than removing the single 2p electron of B.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-186","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Nitrogen has a higher first ionisation enthalpy than oxygen because N has a","options":["filled 2s² 2p⁶ shell","half-filled 2p³ set","larger nuclear charge than O","d-orbital vacancy"],"answer_index":1,"explanation":"The extra stability of half-filled 2p³ outweighs the one-unit rise in Z from N to O.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-187","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Magnesium shows a higher first ionisation enthalpy than aluminium, an exception similar to","options":["Na versus Ar","Be versus B","F versus Ne","K versus Ca"],"answer_index":1,"explanation":"Mg (3s²) is harder to ionise than Al (3p¹), just as Be (2s²) is harder than B (2p¹).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-188","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Phosphorus has a higher first ionisation enthalpy than sulphur because of the extra stability of the","options":["filled 3s² 3p⁶ set","half-filled 3p³ configuration","empty 3d subshell of S","metallic bond in phosphorus"],"answer_index":1,"explanation":"P is 3p³; the paired 3p⁴ electron of S is easier to remove, so IE(P) > IE(S).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-189","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Between lithium and beryllium, beryllium has the greater first ionisation enthalpy because of its","options":["lower Zeff and 2p¹ configuration","higher Zeff and 2s² configuration","much larger radius","noble-gas core of argon"],"answer_index":1,"explanation":"Be is smaller, has one extra proton and a filled 2s pair, so IE₁(Be) > IE₁(Li).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-190","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The second ionisation enthalpy of sodium is very large because the second electron must be taken from the","options":["3s¹ valence orbital","neon-like 2p⁶ core","4s subshell","empty 3d set"],"answer_index":1,"explanation":"After loss of 3s¹, Na⁺ is isoelectronic with Ne; breaking that closed shell requires a large IE₂.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-191","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"First ionisation enthalpy falls in the order Li > Na > K because","options":["nuclear charge falls down the group","atomic size increases down the group","the number of valence electrons increases","they become noble gases"],"answer_index":1,"explanation":"The ns¹ electron is farther from the nucleus and more shielded in Na and K than in Li.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-192","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Although oxygen has a higher nuclear charge than nitrogen, its first ionisation enthalpy is lower because","options":["oxygen has the larger atomic radius","the extra electron in 2p⁴ is paired and is easier to remove","nitrogen has a filled 2p⁶ shell","oxygen lacks a 2s subshell"],"answer_index":1,"explanation":"Size would suggest IE(O) > IE(N), but pairing repulsion in 2p⁴ reverses the trend.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-193","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Boron has a lower first ionisation enthalpy than beryllium even though B is smaller, because","options":["the 2p electron of B is shielded by 2s² and is easier to remove than a 2s electron of Be","boron has a noble-gas configuration","beryllium has a half-filled 2p set","nuclear charge falls from Be to B"],"answer_index":0,"explanation":"The two trends conflict: smaller size would raise IE, but the change of subshell (2s → 2p) lowers it, and the subshell effect wins.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-194","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"For magnesium, the jump between IE₂ and IE₃ is much larger than between IE₁ and IE₂ because the third electron","options":["comes from the 3s subshell","comes from the neon core","is a 3p electron of Al","enters a 4s orbital"],"answer_index":1,"explanation":"Mg is 3s², so IE₁ and IE₂ remove valence electrons; IE₃ must break the 2p⁶ core and is therefore very large.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ionization-enthalpy","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-195","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Electron gain enthalpy is the enthalpy change when an electron is added to a neutral gaseous atom to form a","options":["cation","uninegative ion","crystal lattice","hydrated proton"],"answer_index":1,"explanation":"The defining process is X(g) + e⁻ → X⁻(g); ΔegH is usually negative when energy is released.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-196","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A more negative electron gain enthalpy means a greater tendency of the atom to","options":["lose a proton","accept an electron","form a cation","expand its nucleus"],"answer_index":1,"explanation":"The more energy released on adding an electron, the more favourable the gain.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"electron-gain","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
